import StyleDictionary from "style-dictionary";
import { register } from "@tokens-studio/sd-transforms";

/**
 * Use the Tokens Studio preprocessor plugin to avoid broken references when working with Tokens Studio JSON.
 *
 * Design Tokens JSON generated by Tokens Studio contains an additional layer in the JSON for the names of "Token Sets".
 * Use the `excludeParentKeys` option to exclude this layer from the output, and avoid broken references.
 * Without this plugin the references would look like `"$value": "{common.basis.text.line-height.md}"` instead of `"$value": "{basis.text.line-height.md}"`.
 */
register(StyleDictionary, {
  excludeParentKeys: true,
});

const sd = new StyleDictionary("config.json");
await sd.buildAllPlatforms();
